+// API keys, role permissions and the audit log of data changes.
+import { AppError } from "../errors.js";
+
+const COOK_WRITES = [
+  /^\/recipes\/[^/]+\/cook$/,
+  /^\/batches\/[^/]+\/waste$/,
+  /^\/temperatures$/,
+  /^\/stocktakes\/[^/]+\/counts$/,
+];
+
+/** Checks the bearer token and role permission for `method` and `path`; returns the API key entry. */
+export function authorize(store, token, method, path) {
+  if (!token) throw new AppError("unauthorized");
+  const apiKey = (store.data.apiKeys ?? []).find((k) => k.key === token);
+  if (!apiKey) throw new AppError("unauthorized");
+  if (!canAccess(apiKey.role, method, path)) throw new AppError("forbidden");
+  return apiKey;
+}
+
+/** True when `role` is allowed to call `method` on `path`. */
+export function canAccess(role, method, path) {
+  if (role === "manager") return true;
+  if (method === "GET" && path !== "/audit") return role === "viewer" || role === "cook";
+  if (role === "cook" && method === "POST") return COOK_WRITES.some((re) => re.test(path));
+  return false;
+}
+
+/** Appends an audit entry for a request that changed data. */
+export function recordAudit(store, { at, keyName, method, path, status }) {
+  store.data.audit ??= [];
+  const entry = { at, keyName, method, path, status };
+  store.data.audit.push(entry);
+  return entry;
+}
+
+/** Audit entries, newest first. */
+export function listAudit(store) {
+  return (store.data.audit ?? [])
+    .map((entry, i) => ({ entry, i }))
+    .sort((a, b) => b.entry.at.localeCompare(a.entry.at) || b.i - a.i)
+    .map(({ entry }) => entry);
+}
